import {seed} from './seed.js';
import {TYPES,RELATIONS,MODEL_NAMES,clone,groups,pendingNodes,filterNodes,neighborhood,safeUrl,validate,encode,decode} from './core.js';
const KEY='tw-semiconductor-atlas-v1';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors={'企業':'#416e58','概念':'#7b8c63','業務／服務':'#59879b','產品／技術':'#bd8b63','敘述':'#9b83a8','公式':'#b79c48','實例':'#a47377'};
const relationColors={'拆解／組成':'#608976','先備知識':'#8b9b76','提供產品或服務':'#538ca4','使用技術':'#b98c64','應用':'#8a85b1','類比／相關':'#9b9890','供應':'#577e9a','客戶':'#a78160','合作':'#7d9c69','競爭':'#bc7978','股權隸屬':'#987ca8'};
let data=clone(seed),storageMessage='';
try{const text=localStorage.getItem(KEY);if(text)data=decode(text);}catch(e){storageMessage='本機資料無法讀取，已載入初始內容；原資料未覆寫。請先匯出或檢查瀏覽器儲存設定。';}
let selected='tsmc',tab='overview',mode='knowledge',x='abstract',y='position',filtered=[],activeCluster=null,compare=[],view={scale:1,tx:0,ty:0},draftNode=null,editingRel=null,importDraft=null,allowSave=!storageMessage;
const node=id=>data.nodes.find(n=>n.id===id), dim=id=>data.dimensions.find(d=>d.id===id);
const companies=()=>data.nodes.filter(n=>n.type==='企業');
const refs=ids=>(ids||[]).filter(id=>node(id)).map(id=>`<button class="ref-chip" data-node="${esc(id)}">${esc(node(id).title)} ↗</button>`).join('');
const tagMap={Fabless:'fabless',Foundry:'foundry',IDM:'idm',OSAT:'osat',EMS:'ems','邏輯':'logic','類比':'analog','混合訊號':'analog','功率元件':'power','射頻':'rf','系統單晶片':'soc','SoC':'soc','矽晶圓':'silicon-wafer','IC 載板':'substrate','晶圓載具':'carrier','光罩載具':'carrier'};
const tags=a=>(a||[]).map(t=>`<button class="tag" ${tagMap[t]&&node(tagMap[t])?`data-node="${tagMap[t]}"`:`data-term="${esc(t)}"`}>${esc(MODEL_NAMES[t]||t)} ↗</button>`).join('');
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500)}
function save(){data.updatedAt=new Date().toISOString();if(!allowSave){toast('原本資料尚未覆寫，請先匯出備份，或重新匯入有效資料。');return false}try{localStorage.setItem(KEY,encode(data));$('#save-state').innerHTML='<i></i> 本機已保存';return true}catch{allowSave=false;$('#save-state').textContent='本機儲存失敗';toast('儲存失敗，請匯出 JSON 備份目前內容。');return false}}
function rebuildControls(){const opts=data.dimensions.map(d=>`<option value="${esc(d.id)}">${esc(d.name)}</option>`).join('');if(!dim(x))x=data.dimensions[0].id;if(!dim(y)||y===x)y=data.dimensions.find(d=>d.id!==x).id;$('#x-axis').innerHTML=opts;$('#y-axis').innerHTML=opts;$('#x-axis').value=x;$('#y-axis').value=y;disableAxes();const typeOld=$('#type-filter').value,roleOld=$('#role-filter').value,coOld=$('#company-filter').value;$('#type-filter').innerHTML='<option value="">全部類型</option>'+TYPES.map(t=>`<option>${t}</option>`).join('');$('#type-filter').value=typeOld;const roles=[...new Set(data.nodes.flatMap(n=>n.classification.activities.map(a=>a.label)))];$('#role-filter').innerHTML='<option value="">全部產業活動</option>'+roles.map(r=>`<option>${esc(r)}</option>`).join('');$('#role-filter').value=roleOld;$('#company-filter').innerHTML='<option value="">全部企業及知識</option>'+companies().map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('');$('#company-filter').value=coOld;$('#total-count').textContent=data.nodes.length;$('#company-count').textContent=companies().length;$('#dimension-count').textContent=data.dimensions.length;$('#legend').innerHTML=TYPES.filter(t=>data.nodes.some(n=>n.type===t)).map(t=>`<span><i style="background:${colors[t]}"></i>${t}</span>`).join('');}
function disableAxes(){$$('#x-axis option').forEach(o=>o.disabled=o.value===y);$$('#y-axis option').forEach(o=>o.disabled=o.value===x)}
function getFilter(){return {search:$('#search').value,type:$('#type-filter').value,role:$('#role-filter').value,company:$('#company-filter').value,mode};}
function refresh(){filtered=filterNodes(data,getFilter());$('#list-count').textContent=filtered.length;$('#list-label').textContent=mode==='company'?'企業索引':'知識索引';$('#node-list').innerHTML=[...filtered].sort((a,b)=>mode==='knowledge'?Number(a.type==='企業')-Number(b.type==='企業'):0).map(n=>`<button class="node-item ${n.id===selected?'active':''}" data-node="${esc(n.id)}"><i class="node-dot" style="background:${colors[n.type]}"></i><span>${esc(n.title)}<small>${esc(n.type==='企業'?n.englishName||n.formalName:n.type+' · '+(n.classification.activities[0]?.label||n.tags?.find(t=>t!==n.type)||'產業知識'))}</small></span><span class="item-arrow">↗</span></button>`).join('')||'<p class="empty">找不到符合的單元。<br>試試其他關鍵字或清除篩選。</p>';$('#pending-count').textContent=pendingNodes(data).length;$('#compare-count').textContent=compare.length;drawGraph();renderCluster();renderDetail();}
function selectNode(id){if(!node(id))return;selected=id;tab='overview';if(!filtered.some(n=>n.id===id)){clearFilters(false);toast('已清除篩選，顯示跳轉的知識單元。')}refresh();$('#detail').scrollTop=0;if(window.innerWidth<1050)$('#detail').scrollIntoView({behavior:'smooth',block:'start'});}
function clearFilters(render=true){$('#search').value='';$('#type-filter').value='';$('#role-filter').value='';$('#company-filter').value='';mode='knowledge';$$('[data-action="mode"]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));if(render){activeCluster=null;refresh()}}
function point(a,b){return {x:108+(a-1)*143,y:514-(b-1)*105}}
function drawGraph(){const gs=groups(filtered,x,y),selectedGroup=gs.find(g=>g.nodes.some(n=>n.id===selected));$('#map-count').textContent=gs.reduce((s,g)=>s+g.nodes.length,0);$('#cluster-count').textContent=gs.length;const countMissing=filtered.length-gs.reduce((s,g)=>s+g.nodes.length,0);const svg=$('#graph');let grid='';for(let i=1;i<=5;i++){const p=point(i,i);grid+=`<line x1="${p.x}" y1="62" x2="${p.x}" y2="528" stroke="#e0e6d9" stroke-dasharray="3 5"/><line x1="94" y1="${p.y}" x2="694" y2="${p.y}" stroke="#e0e6d9" stroke-dasharray="3 5"/><text x="${p.x}" y="550" text-anchor="middle" fill="#8c9b82" font-size="12" font-family="monospace">${i}</text><text x="78" y="${p.y+4}" text-anchor="middle" fill="#8c9b82" font-size="12" font-family="monospace">${i}</text>`;}let lines='';const map=new Map(gs.flatMap(g=>g.nodes.map(n=>[n.id,g])));if($('#show-lines').checked&&selectedGroup){const seen=new Set();for(const r of data.relations.filter(r=>r.source===selected||r.target===selected)){const a=map.get(r.source),b=map.get(r.target);if(!a||!b||a.key===b.key)continue;const dedup=[a.key,b.key,r.type].join('|');if(seen.has(dedup))continue;seen.add(dedup);const p=point(a.x,a.y),q=point(b.x,b.y);const aMid=(p.x+q.x)/2,bMid=(p.y+q.y)/2;lines+=`<g><path d="M${p.x},${p.y} L${q.x},${q.y}" stroke="${relationColors[r.type]}" opacity=".58" stroke-width="1.5" stroke-dasharray="${r.type==='股權隸屬'?'3 4':'0'}" marker-end="url(#arrow)"/><title>${esc(node(r.source).title+' → '+r.type+' → '+node(r.target).title+'；'+r.status)}</title><rect x="${aMid-27}" y="${bMid-8}" width="54" height="15" fill="#fff" opacity=".92" rx="3"/><text x="${aMid}" y="${bMid+3}" text-anchor="middle" fill="${relationColors[r.type]}" font-size="7">${esc(r.type)}</text></g>`;}}
const dots=gs.map(g=>{const p=point(g.x,g.y),sel=g===selectedGroup,r=g.nodes.length>1?Math.min(27,19+Math.log2(g.nodes.length)*2):16,col=sel?'#365e43':colors[g.nodes[0].type],title=g.nodes.map(n=>n.title).join('、'),label=sel?node(selected).title:g.nodes[0].title,other=g.nodes.length>1?` +${g.nodes.length-1}`:'';return `<g class="graph-cluster" data-cluster="${g.key}" tabindex="0" role="button" aria-label="座標 ${g.x}, ${g.y}：${g.nodes.length} 個單元，${esc(title)}" transform="translate(${p.x},${p.y})"><title>${esc(title)}</title>${sel?`<circle r="${r+9}" fill="#e0ebcc" opacity=".7"/><circle r="${r+5}" fill="none" stroke="#bacb9f" stroke-width=".8"/>`:''}<circle class="cluster-main" r="${r}" fill="${sel?'#d5e5ac':'#fff'}" stroke="${col}" stroke-width="1.3"/><text text-anchor="middle" y="5" fill="${col}" font-size="${g.nodes.length>1?16:13}" font-family="Georgia,serif">${g.nodes.length>1?g.nodes.length:'•'}</text><rect x="-70" y="${r+9}" width="140" height="19" rx="4" fill="${sel?'#edf2e6':'#ffffffdd'}"/><text text-anchor="middle" y="${r+22}" font-size="10" fill="${sel?'#38583c':'#6e7c66'}">${esc(label.length>12?label.slice(0,11)+'…':label)}${other}</text></g>`}).join('');
svg.innerHTML=`<defs><marker id="arrow" viewBox="0 0 10 10" refX="27" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#9aad8d"/></marker></defs><g id="world" transform="translate(${view.tx} ${view.ty}) scale(${view.scale})"><rect x="94" y="77" width="600" height="451" fill="#f9fbf5" opacity=".5" rx="4"/>${grid}<line x1="94" y1="528" x2="710" y2="528" stroke="#adbaa3"/><line x1="94" y1="528" x2="94" y2="62" stroke="#adbaa3"/>${lines}${dots}</g><text x="395" y="589" text-anchor="middle" font-size="12" fill="#627759">${esc(dim(x).name)} →</text><text transform="translate(30 295) rotate(-90)" text-anchor="middle" font-size="12" fill="#627759">${esc(dim(y).name)} →</text>${!gs.length?'<text x="400" y="280" text-anchor="middle" fill="#7c8b76" font-size="15">沒有可繪製的已評分單元</text>':''}${countMissing?`<text x="775" y="22" text-anchor="end" fill="#9a825e" font-size="10">${countMissing} 個單元缺少此軸評分</text>`:''}`;$('#zoom-level').textContent=Math.round(view.scale*100)+'%';}
function renderCluster(){const p=$('#cluster-panel'),g=groups(filtered,x,y).find(g=>g.key===activeCluster);if(!g){p.hidden=true;return}p.hidden=false;p.innerHTML=`<div class="cluster-heading"><b>座標 (${g.x}, ${g.y}) · ${g.nodes.length} 個知識單元</b><button data-action="close-cluster" aria-label="關閉座標清單">×</button></div><p class="form-hint">${esc(dim(x).name)} ${g.x} 分 / ${esc(dim(y).name)} ${g.y} 分。展開不改變分數。</p><div class="cluster-grid">${g.nodes.map(n=>`<button data-node="${esc(n.id)}"><i class="node-dot" style="background:${colors[n.type]};margin:0"></i>${esc(n.title)}<small>${esc(n.type)}</small></button>`).join('')}</div>`;}
function classification(n){const c=n.classification;return `<div class="classification"><p>產業活動 · 主要 / 其他</p>${c.activities.map(a=>`<button class="tag ${a.priority==='其他'?'secondary':''}" data-role="${esc(a.label)}">${esc(a.label)}${a.priority==='其他'?' · 其他':''}</button>`).join('')}<p>商業模式</p>${tags(c.models)}<p>產品與技術領域</p>${tags(c.domains)}<p>下游應用</p>${tags(c.applications)}${(n.tags||[]).filter(t=>![n.type,...c.activities.map(a=>a.label),...c.models,...c.domains,...c.applications].includes(t)).length?`<p>知識標籤</p>${tags(n.tags.filter(t=>![n.type,...c.activities.map(a=>a.label),...c.models,...c.domains,...c.applications].includes(t)))}`:''}</div>`;}
function sourceCards(sources){return sources.length?sources.map(s=>`<div class="source-card">${safeUrl(s.url)?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`:esc(s.title)}<p>發布：${esc(s.publishedAt)}<br>適用：${esc(s.period)}<br>最後查核：${esc(s.checkedAt)}</p></div>`).join(''):'<p class="empty">尚無來源，請編輯補充；內容應視為待查證。</p>';}
function relationRows(n,list){return list.map(r=>{const outgoing=r.source===n.id,other=outgoing?r.target:r.source;return `<div class="relation-row"><div class="rel-type"><span style="color:${relationColors[r.type]}">${outgoing?'→':'←'} ${esc(r.type)} · ${esc(r.status)}</span><button class="edit-rel" data-edit-relation="${esc(r.id)}">編輯</button></div>${refs([other])}${r.note?`<p>${esc(r.note)}</p>`:''}${r.sources?.length?`<a class="inline-link" href="${esc(safeUrl(r.sources[0].url)||'#')}" target="_blank" rel="noopener noreferrer">來源 · ${esc(r.sources[0].period)} · 查核 ${esc(r.sources[0].checkedAt)}</a>`:''}</div>`}).join('')||'<p class="empty">尚未建立此類關係</p>';}
function renderDetail(){const n=node(selected);if(!n){$('#detail').innerHTML='<p class="empty">選擇一個知識單元開始探索。</p>';return}const rels=data.relations.filter(r=>r.source===n.id||r.target===n.id);let body='';if(tab==='overview'){body=`${classification(n)}${n.answers?.length?n.answers.map((a,i)=>`<section class="question"><h3><b>0${i+1}</b>${esc(a.question)}</h3><p>${esc(a.text)}</p>${refs(a.refs)}<div class="badge-verified">${esc(a.status||n.status)}</div></section>`).join(''):`<p class="body-copy">${esc(n.detail)}</p>`}${n.answers?.length?`<details class="question"><summary>延伸說明與法人資料</summary><p class="body-copy">${esc(n.detail)}</p><p>${esc(n.formalName||'')}<br>${esc((n.aliases||[]).join(' / '))}</p></details>`:''}${n.note?`<div class="meta-note">${esc(n.note)}</div>`:''}<h3 class="section-label">往下探索 · 組成與先備知識</h3>${relationRows(n,rels.filter(r=>['拆解／組成','先備知識','提供產品或服務','使用技術'].includes(r.type)).slice(0,8))}`;}else if(tab==='scores'){body=`<div class="meta-note">評分對象是這個單元的知識特性。企業節點評的是概況說明，不代表技術能力、規模或經營績效。初始分數為可修訂的編輯判斷。</div>${data.dimensions.map(d=>{const s=n.scores[d.id];return `<div class="score-row"><div><h3>${esc(d.name)}</h3><b>${s?.value??'—'}<small style="font-size:10px"> / 5</small></b></div><div class="score-bar"><span style="width:${(s?.value||0)*20}%"></span></div><p>${esc(s?.reason||'尚未評分。請編輯補上分數與理由。')}</p></div>`}).join('')}<button class="button" data-action="edit-node">編輯分數與理由</button> <button class="text-button" data-action="rubric">完整評分表 ↗</button>`;}else if(tab==='relations'){body=`<p class="form-hint">箭頭以目前節點為基準。股權隸屬獨立於知識拆解；具名企業關係須附來源。</p><button class="button" data-action="new-relation">＋ 建立關係</button><h3 class="form-title">上下層知識單元</h3>${relationRows(n,rels.filter(r=>r.type==='拆解／組成'))}<h3 class="form-title">其他知識與業務關係</h3>${relationRows(n,rels.filter(r=>!['拆解／組成','股權隸屬'].includes(r.type)))}<h3 class="form-title">集團 / 股權隸屬</h3>${relationRows(n,rels.filter(r=>r.type==='股權隸屬'))}`;}else{body=`<span class="pill">${esc(n.status)}</span><p class="form-hint">事實依來源整理；客戶需求、比較與概念拆解等分析在內文明確標示。未標示發布日的頁面只代表查核當日可見內容。</p>${sourceCards(n.sources)}${n.note?`<div class="meta-note">${esc(n.note)}</div>`:''}<p class="form-hint">節點 ID：${esc(n.id)}<br>最後修改：${esc(n.updatedAt||'初始資料 2026-10-28')}</p><button class="button" data-action="edit-node">編輯內容與來源</button>`;}
$('#detail').innerHTML=`<div class="detail-header"><div class="detail-kicker"><span>KNOWLEDGE UNIT / ${esc(n.id.toUpperCase())}</span><span class="pill">${esc(n.type)}</span></div><h2>${esc(n.title)}</h2><div class="english">${esc(n.englishName||n.formalName||'CONNECTED KNOWLEDGE')}</div><p class="definition">${esc(n.definition)}</p><div class="detail-actions">${n.type==='企業'?`<button class="small-button filled" data-compare-id="${esc(n.id)}">${compare.includes(n.id)?'✓ 已加入比較':'＋ 加入比較'}</button>`:''}<button class="small-button" data-action="edit-node">編輯單元</button><button class="small-button" data-action="copy-node">引用</button></div></div><div class="detail-tabs">${[['overview','概況'],['scores','評分'],['relations',`關係 ${rels.length}`],['sources','來源']].map(([id,label])=>`<button class="${tab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div><div class="detail-body">${body}</div>`;}
function modal(title,subtitle,body){$('#modal-body').innerHTML=`<div class="modal-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="modal-close" data-action="close-modal" aria-label="關閉視窗">×</button></div><div class="modal-content">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function addCompare(id){if(compare.includes(id))compare=compare.filter(n=>n!==id);else if(compare.length<3)compare.push(id);else{toast('最多比較三家企業，請先取消其中一家。');return}$('#compare-count').textContent=compare.length;renderDetail();if($('#compare-table'))showCompare();else toast(compare.includes(id)?'已加入比較；從上方「企業比較」開啟。':'已移出比較。');}
function showCompare(){const chosen=compare.map(node).filter(Boolean);const rows=[['主要業務',n=>`<p>${esc(n.answers?.[0]?.text||n.definition)}</p>${refs(n.answers?.[0]?.refs)}`],['商業模式',n=>`${tags(n.classification.models)}${refs((n.answers?.[3]?.refs||[]).filter(id=>['foundry','fabless','idm','osat','ems'].includes(id)))}`],['親自完成 / 交付物',n=>`<p>${esc(n.answers?.[1]?.text||n.detail)}</p>${refs(n.answers?.[1]?.refs)}`],['服務對象與需求',n=>`<p>${esc(n.answers?.[2]?.text||'待補充')}</p>${refs(n.answers?.[2]?.refs)}`],['參與的產業活動',n=>`${n.classification.activities.map(a=>`<button class="ref-chip" data-role="${esc(a.label)}">${esc(a.label)} · ${a.priority} ↗</button>`).join('')}${refs(n.answers?.[3]?.refs)}`],['產品與技術',n=>`${tags(n.classification.domains)}${refs(n.technologyRefs||[...new Set([...(n.answers?.[0]?.refs||[]),...(n.answers?.[4]?.refs||[])])].filter(id=>['產品／技術','業務／服務'].includes(node(id)?.type)))}`],['先懂這些概念',n=>refs(n.prerequisiteRefs||n.answers?.[4]?.refs)],['差異與環節銜接',n=>`<p>${esc(n.answers?.[5]?.text||'待補充')}</p>${refs(n.answers?.[5]?.refs)}`]];
modal('企業並排比較','選擇 2–3 家企業；每個概念與產業活動都可回到知識圖。',`<div class="compare-picker">${companies().map(n=>`<button class="compare-pick ${compare.includes(n.id)?'selected':''}" data-compare-id="${esc(n.id)}">${compare.includes(n.id)?'✓ ':''}${esc(n.title)}</button>`).join('')}</div><div id="compare-table">${chosen.length<2?'<p class="empty">先選擇兩家企業，看看它們如何分工。</p>':`<div class="comparison"><table><thead><tr><th>定位觀察</th>${chosen.map(n=>`<th><h3 class="company-title"><button data-node="${esc(n.id)}">${esc(n.title)} ↗</button></h3><p>${esc(n.definition)}</p></th>`).join('')}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr><th>${label}</th>${chosen.map(n=>`<td>${fn(n)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="form-hint">這是依業務範圍整理的分析性比較，不表示能力高低、特定交易或實際客戶關係。來源見各企業詳情。</p>`}</div>`);}
function showRubric(){modal('知識屬性評分表','所有維度採 1–5 分；2、4 分有獨立判準。評分可修訂，產業分類不轉換為優劣分數。',`<div class="rubric-scroll"><table class="rubric-table"><thead><tr><th>維度</th>${[1,2,3,4,5].map(i=>`<th><span class="rule-scale">${i}</span> 分</th>`).join('')}</tr></thead><tbody>${data.dimensions.map(d=>`<tr><th>${esc(d.name)}<br><button class="inline-link" data-edit-dimension="${esc(d.id)}">編輯規則</button></th>${[1,2,3,4,5].map(i=>`<td>${esc(d.rules[i])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="meta-note">新增維度後，既有節點在該維度暫無評分，會列於「待評分」。修改規則不自動更動既有分數，請重新檢視評分理由。</div><button class="button" data-action="new-dimension">＋ 新增自訂維度</button>`);}
function showPending(){const pending=pendingNodes(data);modal('待評分單元',`共有 ${pending.length} 個單元尚未完成全部維度。座標只需當前兩軸有分數；待評分清單檢查所有維度。`,pending.map(n=>`<div class="relation-row">${refs([n.id])}<p>待補：${data.dimensions.filter(d=>!Number.isInteger(n.scores[d.id]?.value)).map(d=>esc(d.name)).join('、')}</p><button class="small-button" data-edit-node="${esc(n.id)}">補上評分</button></div>`).join('')||'<div class="empty">所有單元已完成評分。新增單元可先留空，稍後補分。</div>');}
function showHelp(){modal('從一家公司，開始探索','所有修改只保存在目前瀏覽器。請定期匯出完整 JSON 備份。',`<ol class="help-list"><li>點選上方台積電、力積電或日月光。右側依六個問題說明定位，綠色連結可一路走到共用概念。</li><li>從左側切換「從知識探索」或「從企業探索」，搜尋名稱、英文名或別名，也可篩選類型、活動與企業相關知識。</li><li>任選不同 X、Y 維度。點的座標只來自評分；數字圈代表多個同座標單元，點擊即可選取。拖曳平移，滾輪或雙指縮放，⤢ 重設視角。</li><li>在企業詳情點「加入比較」，選 2–3 家後開啟「企業比較」。活動、產品領域與商業模式分開看。</li><li>「編輯單元」可改文字、分類、評分理由、問答與來源；「關係」分頁可新增或編輯連結。股權關係另列，與知識組成分開。</li><li>「評分規則」提供完整 1–5 分表，也可新增維度。「待評分」可補上缺少的分數。</li><li>「資料管理」可匯出、驗證與匯入完整 JSON。匯入前先顯示摘要，確認後才取代。不同瀏覽器與裝置不會自動同步。</li></ol><p class="meta-note">第一版含 60 個節點、16 個企業法人；為保留日月光投控與營運公司差異，比原定約 15 家多一筆。官網沒有發布日期時明記「未標示」，分類與初始評分均可修訂。</p>`);}
function download(){const blob=new Blob([encode(data)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='taiwan-semiconductor-atlas-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('已匯出完整 JSON。');}
function showData(){modal('資料管理','本機儲存 · 完整 JSON 可攜備份 · 不含帳戶同步',`<div class="data-grid"><section class="data-card"><h3>把你的研究帶走</h3><p>目前 ${data.nodes.length} 個知識單元、${data.relations.length} 條關係、${data.dimensions.length} 個維度。包含分類、問答、來源、分數與評分規則。</p><button class="button primary" data-action="export">↓ 匯出完整 JSON</button></section><section class="data-card"><h3>接續你的研究</h3><p>先驗證資料與引用，確認後取代目前資料。建議先匯出備份。</p><label class="file-label">選擇 JSON 檔案<input type="file" id="import-file" accept=".json,application/json"></label></section></div><label class="form-label" style="margin-top:20px">也可貼上完整 JSON<textarea id="import-text" rows="5" placeholder='{"schemaVersion":1,"nodes":[…],"relations":[…],"dimensions":[…]}'></textarea></label><div class="modal-actions"><button class="button" data-action="validate-import">驗證貼上的 JSON</button></div><div id="import-result"></div><div id="import-error" class="validation-error"></div><h3 class="form-title">編輯工具</h3><button class="button" data-action="new-node">＋ 新增知識單元</button> <button class="button" data-action="new-relation">＋ 建立關係</button> <button class="button" data-action="rubric">維度與評分規則</button><p class="form-hint">資料格式版本 1。日期與分類是內容資料；瀏覽器本機儲存不會回傳修改到網站伺服器。清除網站資料會清除本機修改。</p>`);}
function previewImport(text){try{importDraft=decode(text);$('#import-error').textContent='';$('#import-result').innerHTML=`<div class="meta-note">驗證通過：${importDraft.nodes.length} 個單元、${importDraft.relations.length} 條關係、${importDraft.dimensions.length} 個維度。<br>確認後會取代目前資料，無法自動復原。</div><button class="button primary" data-action="confirm-import">確認取代並匯入</button>`;}catch(e){importDraft=null;$('#import-result').innerHTML='';$('#import-error').textContent='匯入失敗，原資料保持不變。\n'+e.message;}}
const split=s=>s.split(/[,，、\n]/).map(s=>s.trim()).filter(Boolean);
function sourceEditor(s={},i=0){return `<div class="source-editor" data-source-row><label>來源標題<input data-source="title" value="${esc(s.title||'')}"></label><label>網址（https://）<input data-source="url" type="url" value="${esc(s.url||'')}"></label><div class="dates"><label>發布日期<input data-source="publishedAt" value="${esc(s.publishedAt||'未標示')}"></label><label>適用期間<input data-source="period" value="${esc(s.period||'')}"></label><label>最後查核<input data-source="checkedAt" value="${esc(s.checkedAt||new Date().toISOString().slice(0,10))}"></label></div><button type="button" data-action="remove-source">移除此來源</button></div>`;}
function collectSources(){return $$('[data-source-row]').map(row=>Object.fromEntries([...row.querySelectorAll('[data-source]')].map(el=>[el.dataset.source,el.value.trim()]))).filter(s=>s.title||s.url);}
function editNode(id){const original=node(id);draftNode=original?clone(original):{id:'node-'+Date.now().toString(36),title:'',type:'概念',definition:'',detail:'',classification:{activities:[],models:[],domains:[],applications:[]},aliases:[],tags:[],scores:{},sources:[],status:'待查證內容',answers:[]};const n=draftNode,c=n.classification;
modal(original?'編輯知識單元':'新增知識單元','文字、分類、來源與分數均可修改；空白分數會進入待評分清單。',`<form id="node-form"><div class="form-grid"><label>標題<input name="title" required value="${esc(n.title)}"></label><label>類型<select name="type">${TYPES.map(t=>`<option ${t===n.type?'selected':''}>${t}</option>`).join('')}</select></label><label class="wide">一句話定義<textarea name="definition" required rows="2">${esc(n.definition)}</textarea></label><label class="wide">詳細內容<textarea name="detail" rows="5">${esc(n.detail)}</textarea></label><label>正式名稱<input name="formalName" value="${esc(n.formalName||'')}"></label><label>英文名稱<input name="englishName" value="${esc(n.englishName||'')}"></label><label>別名（逗號分隔）<input name="aliases" value="${esc((n.aliases||[]).join('、'))}"></label><label>標籤（逗號分隔）<input name="tags" value="${esc((n.tags||[]).join('、'))}"></label><label>查證狀態<select name="status">${['已查證事實','分析性解釋','待查證內容'].map(s=>`<option ${s===n.status?'selected':''}>${s}</option>`).join('')}</select></label><label>說明或限制<input name="note" value="${esc(n.note||'')}"></label></div><h3 class="form-title">產業分類 · 各欄均可多選（逗號分隔）</h3><div class="form-grid"><label>主要產業活動<input name="activities-primary" value="${esc(c.activities.filter(a=>a.priority==='主要').map(a=>a.label).join('、'))}"></label><label>其他產業活動<input name="activities-other" value="${esc(c.activities.filter(a=>a.priority==='其他').map(a=>a.label).join('、'))}"></label><label>商業模式<input name="models" value="${esc(c.models.join('、'))}" placeholder="Fabless、Foundry、IDM、OSAT…"></label><label>產品與技術領域<input name="domains" value="${esc(c.domains.join('、'))}"></label><label class="wide">下游應用<input name="applications" value="${esc(c.applications.join('、'))}"></label></div><h3 class="form-title">評分與理由</h3><p class="form-hint">每個分數都需附理由。評分是編輯判斷，企業節點評的是概況說明。</p>${data.dimensions.map(d=>`<div class="score-editor"><label for="score-${esc(d.id)}">${esc(d.name)}</label><select id="score-${esc(d.id)}" name="score:${esc(d.id)}"><option value="">待評分</option>${[1,2,3,4,5].map(v=>`<option value="${v}" ${n.scores[d.id]?.value===v?'selected':''}>${v} 分</option>`).join('')}</select><input name="reason:${esc(d.id)}" value="${esc(n.scores[d.id]?.reason||'')}" placeholder="用一句話說明此分數的理由" aria-label="${esc(d.name)}評分理由"></div>`).join('')}<h3 class="form-title">可核對的來源</h3><div id="source-editors">${n.sources.map(sourceEditor).join('')}</div><button class="button" type="button" data-action="add-source">＋ 新增來源</button><details style="margin-top:18px"><summary style="font-size:12px">企業六題問答（進階編輯）</summary><p class="form-hint">陣列中每題包含 question、text、refs（節點 ID 陣列）、status。概念節點可留空陣列。</p><label class="form-label"><textarea name="answers" rows="12" style="font-family:monospace;font-size:11px">${esc(JSON.stringify(n.answers||[],null,2))}</textarea></label></details><div id="edit-error" class="validation-error"></div><div class="modal-actions"><button type="button" class="button" data-action="close-modal">取消</button><button type="submit" class="button primary">保存單元</button></div></form>`);}
function submitNode(e){e.preventDefault();const form=e.target,fd=new FormData(form),n=clone(draftNode);for(const k of ['title','type','definition','detail','formalName','englishName','status','note'])n[k]=String(fd.get(k)||'').trim();n.aliases=split(fd.get('aliases'));n.tags=split(fd.get('tags'));n.classification={activities:[...split(fd.get('activities-primary')).map(label=>({label,priority:'主要'})),...split(fd.get('activities-other')).map(label=>({label,priority:'其他'}))],models:split(fd.get('models')),domains:split(fd.get('domains')),applications:split(fd.get('applications'))};n.scores={};for(const d of data.dimensions){const value=fd.get('score:'+d.id);n.scores[d.id]={value:value?Number(value):null,reason:String(fd.get('reason:'+d.id)||'').trim(),status:'編輯判斷'};}n.sources=collectSources();try{n.answers=JSON.parse(fd.get('answers')||'[]');}catch{$('#edit-error').textContent='企業問答 JSON 格式無效，請修正後再保存。';return}n.updatedAt=new Date().toISOString();const next=clone(data),i=next.nodes.findIndex(x=>x.id===n.id);if(i<0)next.nodes.push(n);else next.nodes[i]=n;const errors=validate(next);if(errors.length){$('#edit-error').textContent=errors.slice(0,10).join('\n');return}data=next;selected=n.id;save();$('#modal').close();rebuildControls();clearFilters(false);refresh();toast('單元已更新'+(allowSave?'並保存。':'；請匯出 JSON 備份。'));}
function editRelation(id){const r=data.relations.find(r=>r.id===id);editingRel=r?clone(r):{id:'rel-'+Date.now().toString(36),source:selected||data.nodes[0]?.id,target:'',type:'類比／相關',note:'',status:'分析性解釋',sources:[]};const e=editingRel;const options=val=>data.nodes.map(n=>`<option value="${esc(n.id)}" ${val===n.id?'selected':''}>${esc(n.title)} · ${esc(n.type)}</option>`).join('');modal(r?'編輯關係':'建立關係','關係有方向；拆解／組成由整體指向部分，先備知識由目前單元指向所需概念。',`<form id="relation-form"><div class="form-grid"><label>起點<select name="source">${options(e.source)}</select></label><label>終點<select name="target" required><option value="">請選擇終點</option>${options(e.target)}</select></label><label>關係類型<select name="type">${RELATIONS.map(t=>`<option ${t===e.type?'selected':''}>${t}</option>`).join('')}</select></label><label>證據性質<select name="status">${['已查證事實','分析性解釋','待查證內容','典型流程示意'].map(t=>`<option ${t===e.status?'selected':''}>${t}</option>`).join('')}</select></label><label class="wide">關係說明<textarea name="note" rows="3">${esc(e.note||'')}</textarea></label></div><div class="meta-note">供應：供應方 → 接收方；客戶：買方 → 服務方；股權隸屬：母公司 → 子公司。合作、競爭僅表示雙方關聯。實際具名企業關係標記「已查證事實」時必須附來源。</div><h3 class="form-title">來源與日期</h3><div id="source-editors">${(e.sources||[]).map(sourceEditor).join('')}</div><button class="button" type="button" data-action="add-source">＋ 新增來源</button><div id="edit-error" class="validation-error"></div><div class="modal-actions">${r?'<button type="button" class="button danger" data-action="delete-relation">刪除關係</button>':''}<button type="submit" class="button primary">保存關係</button></div></form>`);}
function submitRelation(e){e.preventDefault();const fd=new FormData(e.target),r=clone(editingRel);for(const k of ['source','target','type','status','note'])r[k]=String(fd.get(k)||'').trim();r.sources=collectSources();const next=clone(data),i=next.relations.findIndex(x=>x.id===r.id);if(i<0)next.relations.push(r);else next.relations[i]=r;const err=validate(next);if(err.length){$('#edit-error').textContent=err.slice(0,10).join('\n');return}data=next;save();$('#modal').close();refresh();tab='relations';renderDetail();toast('關係已保存。');}
function editDimension(id){const d=dim(id)||{id:'dim-'+Date.now().toString(36),name:'',min:1,max:5,rules:{}};modal(id?'編輯評分規則':'新增自訂維度','維度採 1–5 分；新增維度不會自動替節點評分。',`<form id="dimension-form" data-id="${esc(d.id)}"><div class="form-grid"><label class="wide">維度名稱<input name="name" value="${esc(d.name)}" required></label>${[1,2,3,4,5].map(i=>`<label class="wide">${i} 分判準<input name="rule${i}" required value="${esc(d.rules[i]||'')}"></label>`).join('')}</div><div id="edit-error" class="validation-error"></div><div class="modal-actions"><button class="button primary" type="submit">保存維度</button></div></form>`);}
function submitDimension(e){e.preventDefault();const fd=new FormData(e.target),id=e.target.dataset.id;const d={id,name:String(fd.get('name')).trim(),min:1,max:5,kind:'編輯判斷',editable:true,rules:Object.fromEntries([1,2,3,4,5].map(i=>[i,String(fd.get('rule'+i)).trim()]))};if(data.dimensions.some(x=>x.id!==id&&x.name===d.name)){$('#edit-error').textContent='已有相同名稱的維度。';return}const next=clone(data),index=next.dimensions.findIndex(x=>x.id===id);if(index<0)next.dimensions.push(d);else next.dimensions[index]=d;const err=validate(next);if(err.length){$('#edit-error').textContent=err.join('\n');return}data=next;save();rebuildControls();refresh();showRubric();toast('維度已保存；既有分數保持原值。');}
function zoom(factor,center={x:400,y:300}){const next=Math.max(.65,Math.min(3,view.scale*factor)),k=next/view.scale;view.tx=center.x-(center.x-view.tx)*k;view.ty=center.y-(center.y-view.ty)*k;view.scale=next;drawGraph();}
let pointers=new Map(),gesture=null,suppressClick=false;
const svgPoint=e=>{const m=$('#graph').getScreenCTM();return new DOMPoint(e.clientX,e.clientY).matrixTransform(m.inverse())};
$('#graph').addEventListener('pointerdown',e=>{if(e.button&&e.button!==0)return;const p=svgPoint(e);pointers.set(e.pointerId,p);if(pointers.size===1){gesture={point:p,view:{...view},moved:0};}else if(pointers.size===2){const [a,b]=[...pointers.values()];gesture={center:{x:(a.x+b.x)/2,y:(a.y+b.y)/2},dist:Math.hypot(a.x-b.x,a.y-b.y),view:{...view},moved:10};suppressClick=true;}$('#graph').setPointerCapture(e.pointerId);});
$('#graph').addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId)||!gesture)return;const p=svgPoint(e);pointers.set(e.pointerId,p);if(pointers.size===1&&gesture.point){const dx=p.x-gesture.point.x,dy=p.y-gesture.point.y;if(Math.abs(dx)+Math.abs(dy)>6){gesture.moved=Math.abs(dx)+Math.abs(dy);suppressClick=true;view.tx=gesture.view.tx+dx;view.ty=gesture.view.ty+dy;drawGraph();}}else if(pointers.size===2&&gesture.dist){const [a,b]=[...pointers.values()],dist=Math.hypot(a.x-b.x,a.y-b.y),c={x:(a.x+b.x)/2,y:(a.y+b.y)/2};view.scale=Math.max(.65,Math.min(3,gesture.view.scale*dist/gesture.dist));const k=view.scale/gesture.view.scale;view.tx=c.x-(gesture.center.x-gesture.view.tx)*k;view.ty=c.y-(gesture.center.y-gesture.view.ty)*k;drawGraph();}});
function endPointer(e){pointers.delete(e.pointerId);if(!pointers.size){gesture=null;setTimeout(()=>suppressClick=false,100)}else{gesture={point:[...pointers.values()][0],view:{...view},moved:10}}}
$('#graph').addEventListener('pointerup',endPointer);$('#graph').addEventListener('pointercancel',endPointer);
$('#graph').addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(-e.deltaY*.0015),svgPoint(e));},{passive:false});
// Pointer capture retargets taps to the SVG; hit-test the cluster at release for touch and mouse.
$('#graph').addEventListener('pointerup',e=>{if(suppressClick)return;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-cluster]');if(target){activeCluster=target.dataset.cluster;renderCluster();$('#cluster-panel').scrollIntoView({behavior:'smooth',block:'nearest'});}});
$('#graph').addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.closest('[data-cluster]')){e.preventDefault();activeCluster=e.target.closest('[data-cluster]').dataset.cluster;renderCluster();}});
document.addEventListener('click',async e=>{const t=e.target.closest('button,[data-node],[data-cluster],[data-tab]');if(!t)return;if(t.dataset.node){$('#modal').close();selectNode(t.dataset.node);return}if(t.dataset.role){$('#modal').close();clearFilters(false);$('#role-filter').value=t.dataset.role;refresh();$('#graph-wrap').scrollIntoView({behavior:'smooth',block:'center'});return}if(t.dataset.term){$('#modal').close();clearFilters(false);$('#search').value=t.dataset.term;refresh();return}if(t.dataset.tab){tab=t.dataset.tab;renderDetail();$('#detail').scrollTop=0;return}if(t.dataset.compareId){addCompare(t.dataset.compareId);return}if(t.dataset.editNode){editNode(t.dataset.editNode);return}if(t.dataset.editRelation){editRelation(t.dataset.editRelation);return}if(t.dataset.editDimension){editDimension(t.dataset.editDimension);return}const a=t.dataset.action;if(!a)return;switch(a){case 'home':$('#modal').close();window.scrollTo({top:0,behavior:'smooth'});break;case 'mode':mode=t.dataset.mode;$('#type-filter').value='';$$('[data-action="mode"]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));activeCluster=null;refresh();break;case 'compare':showCompare();break;case 'filters':$('#sidebar').classList.toggle('open');break;case 'clear-filters':clearFilters();break;case 'swap':[x,y]=[y,x];$('#x-axis').value=x;$('#y-axis').value=y;disableAxes();activeCluster=null;refresh();break;case 'rubric':showRubric();break;case 'data':showData();break;case 'pending':showPending();break;case 'help':showHelp();break;case 'zoom-in':zoom(1.2);break;case 'zoom-out':zoom(1/1.2);break;case 'reset-view':view={scale:1,tx:0,ty:0};drawGraph();break;case 'close-cluster':activeCluster=null;renderCluster();break;case 'close-modal':$('#modal').close();break;case 'new-node':editNode(null);break;case 'edit-node':editNode(selected);break;case 'new-relation':editRelation(null);break;case 'new-dimension':editDimension(null);break;case 'add-source':$('#source-editors').insertAdjacentHTML('beforeend',sourceEditor());break;case 'remove-source':t.closest('[data-source-row]').remove();break;case 'export':download();break;case 'validate-import':previewImport($('#import-text').value);break;case 'confirm-import':if(importDraft){data=importDraft;importDraft=null;allowSave=true;save();selected=data.nodes[0]?.id||null;compare=[];rebuildControls();clearFilters(false);refresh();$('#modal').close();toast('JSON 已匯入，完整資料已載入。')}break;case 'delete-relation':data.relations=data.relations.filter(r=>r.id!==editingRel.id);save();$('#modal').close();refresh();toast('關係已刪除。');break;case 'copy-node':{const n=node(selected);const text=`${n.title}（${n.type}）\n${n.definition}\n節點 ID：${n.id}\n${n.sources.map(s=>s.url+'（查核 '+s.checkedAt+'）').join('\n')}`;try{await navigator.clipboard.writeText(text);toast('已複製節點引用與來源。')}catch{modal('引用知識單元','複製以下文字與來源。',`<label class="form-label"><textarea rows="9">${esc(text)}</textarea></label>`)}break;}}});
document.addEventListener('submit',e=>{if(e.target.id==='node-form')submitNode(e);else if(e.target.id==='relation-form')submitRelation(e);else if(e.target.id==='dimension-form')submitDimension(e)});
document.addEventListener('change',async e=>{if(e.target.id==='import-file'){const f=e.target.files[0];if(!f)return;if(f.size>15e6){$('#import-error').textContent='檔案大於 15 MB，請確認檔案內容。';return}try{previewImport(await f.text())}catch{$('#import-error').textContent='無法讀取檔案。'}}});
$('#search').addEventListener('input',()=>{activeCluster=null;refresh()});['type-filter','role-filter','company-filter'].forEach(id=>$('#'+id).addEventListener('change',()=>{activeCluster=null;refresh()}));
$('#x-axis').addEventListener('change',e=>{if(e.target.value===y)return;x=e.target.value;disableAxes();activeCluster=null;refresh()});$('#y-axis').addEventListener('change',e=>{if(e.target.value===x)return;y=e.target.value;disableAxes();activeCluster=null;refresh()});$('#show-lines').addEventListener('change',drawGraph);
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#sidebar').classList.add('open');$('#search').focus()}});
rebuildControls();if(!node(selected))selected=data.nodes[0]?.id;refresh();if(storageMessage){$('#save-state').textContent='儲存待確認';setTimeout(()=>toast(storageMessage),600)}else{try{if(!localStorage.getItem(KEY))save()}catch{$('#save-state').textContent='本機儲存不可用';allowSave=false}}
